{"command": "cd /root && python -c "
import pandas as pd, numpy as np
from collections import Counter
df = pd.read_excel('/root/data.xlsx', sheet_name='Data', header=8, usecols='C:J')
df = df.dropna(subset=['Turn number']).astype(int).reset_index(drop=True)
def score_turn(r):
    c = Counter(r); hi,lo=max(r),min(r)
    s_run=0
    for i in range(3):
        d=[r[i+1]-r[i],r[i+2]-r[i+1],r[i+3]-r[i+2]]
        if d==[1,1,1] or d==[-1,-1,-1]: s_run=50;break
    return dict(HO=hi*c[hi],Sum=sum(r),HL=hi*lo*(hi-lo),TN=30 if len(set(r))==2 else 0,AN=40 if set(r)=={1,2,3,4,5,6} else 0,R4=s_run)
# find game with max
for g in [3000]:
    grp = df[df['Game number']==g]
    for _,row in grp.iterrows():
        rolls = [row[f'Roll {i}'] for i in range(1,7)]
        print(rolls, score_turn(rolls))
"", "security_risk": "LOW", "summary": "Debug max score"}

